		return new Promise((resolve) => {
			const { dx, dy, direction, scrollToEnd } = params;

			// Store current scrollBehavior for restoration later.
			const originalScrollBehavior = getComputedStyle(document.documentElement).scrollBehavior;

			// Cleanup to restore the original scrollBehavior.
			const cleanup = () => {
				document.documentElement.style.scrollBehavior = originalScrollBehavior;
				document.removeEventListener("scrollend", cleanup);
				clearTimeout(timeout);
				resolve();
			}

			// Start a timeout to handle cases where "scrollend" does not trigger. That is when scrolling at the end of the page.
			// 1 second timeout is enough to cover smooth scrolls (~500 ms) plus event triggering delays even on slower machines.
			const timeout = setTimeout(() => {
				cleanup();
			}, 1000);

			document.addEventListener("scrollend", cleanup, { once: true });

			// Set scroll behavior to smooth. Handles the cases where this is disabled.
			document.documentElement.style.scrollBehavior = 'smooth';

			// Handle special behaviors.
			if (direction === "left") {
				if (scrollToEnd) {
					window.scrollTo(0, window.scrollY);
				} else {
					window.scrollBy(dx, 0);
				}
			} else if (direction === "right") {
				if (scrollToEnd) {
					window.scrollTo(document.documentElement.scrollWidth, window.scrollY);
				} else {
					window.scrollBy(dx, 0);
				}
			} else if (direction === "up") {
				if (scrollToEnd) {
					window.scrollTo(window.scrollX, 0);
				} else {
					window.scrollBy(0, dy);
				}
			} else if (direction === "down") {
				if (scrollToEnd) {
					window.scrollTo(window.scrollX, document.documentElement.scrollHeight);
				} else {
					window.scrollBy(0, dy);
				}
			} else {
				console.error("Invalid direction: " + direction);
				cleanup();
			}
		});
