/**
 * Shows an animated dotted line between two points with dots appearing one by
 * one
 * @param {{startX: number, startY: number, endX: number, endY: number, color:
 *     string}=} args
 * @return {Promise<{}>}
 */
(args = {startX: 0, startY: 0, endX: 0, endY: 0, color: '#0066ff'}) => {
  const {startX, startY, endX, endY, color} = args;

  const ANIMATION_DURATION = 400;  // Duration of the animation in ms
  const TRAIL_LENGTH = 80;         // Length of the trail in pixels
  const CIRCLE_RADIUS = 6;         // Radius of the moving circle
  const PULSE_DURATION = 150;      // Duration for pulse animation

  /**
   * Performs pulse animation
   * @param {!SVGCircleElement} circle
   * @return {!Promise<void>}
   */
  async function performPulse(circle) {
    return new Promise((resolve) => {
      circle.style.transition = `r ${PULSE_DURATION}ms ease-in-out`;
      circle.setAttribute('r', CIRCLE_RADIUS * 1.2);

      setTimeout(() => {
        circle.setAttribute('r', CIRCLE_RADIUS);
        setTimeout(() => {
          resolve();
        }, PULSE_DURATION);
      }, PULSE_DURATION);
    });
  }

  async function showDragAnimation() {
    // Create SVG container
    const container = document.createElement('div');
    container.id = 'jetski-drag-ui-container';
    Object.assign(container.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      width: '100%',
      height: '100%',
      pointerEvents: 'none',
      zIndex: '2147483647'
    });
    document.body.appendChild(container);

    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    Object.assign(svg.style, {
      position: 'absolute',
      top: '0',
      left: '0',
      width: '100%',
      height: '100%'
    });
    container.appendChild(svg);

    // Create trail path
    const trail =
        document.createElementNS('http://www.w3.org/2000/svg', 'path');
    trail.setAttribute('stroke', color);
    trail.setAttribute('stroke-width', '6');
    trail.setAttribute('stroke-linecap', 'round');
    trail.setAttribute('fill', 'none');
    trail.style.opacity = '0.3';
    svg.appendChild(trail);

    // Create moving circle
    const circle =
        document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('r', CIRCLE_RADIUS);
    circle.setAttribute('fill', color);
    circle.style.opacity = '0.9';
    svg.appendChild(circle);

    // Calculate distance and animation parameters
    const dx = endX - startX;
    const dy = endY - startY;
    const distance = Math.sqrt(dx * dx + dy * dy);
    const steps = Math.ceil(ANIMATION_DURATION / 16);
    const stepDelay = ANIMATION_DURATION / steps;

    // Position circle at start
    circle.setAttribute('cx', startX);
    circle.setAttribute('cy', startY);

    // Press pulse at start position
    await performPulse(circle);

    // Animate the circle and trail using requestAnimationFrame
    const startTime = performance.now();

    await new Promise(resolve => {
      function animate(currentTime) {
        const elapsed = currentTime - startTime;
        const linearProgress = Math.min(elapsed / ANIMATION_DURATION, 1);

        // Apply ease-out cubic easing
        const progress = 1 - Math.pow(1 - linearProgress, 3);

        const currentX = startX + dx * progress;
        const currentY = startY + dy * progress;

        // Update circle position
        circle.setAttribute('cx', currentX);
        circle.setAttribute('cy', currentY);

        // Calculate trail start point (behind the circle)
        const trailDistance = Math.min(TRAIL_LENGTH, distance * progress);
        const trailProgress = Math.max(0, progress - (TRAIL_LENGTH / distance));
        const trailStartX = startX + dx * trailProgress;
        const trailStartY = startY + dy * trailProgress;

        // Update trail path
        trail.setAttribute(
            'd', `M ${trailStartX} ${trailStartY} L ${currentX} ${currentY}`);

        if (linearProgress < 1) {
          requestAnimationFrame(animate);
        } else {
          resolve();
        }
      }

      requestAnimationFrame(animate);
    });

    // Release pulse at end position
    await performPulse(circle);

    // Remove container
    container.remove();

    return {};
  }

  return showDragAnimation();
};
